/**
 * Кэш повторного открытия карточки взаимодействия.
 *
 * Карточка — самый частый экран системы и самый дорогой: за одно её открытие
 * уходит десяток выборок, и половина из них — лента комментариев и история
 * правок, которые у долгого взаимодействия насчитывают сотни строк, а меняются
 * только когда по записи что-то произошло.
 *
 * Поколение здесь — не счётчик, а `interactions.last_activity_at`: его двигает
 * каждое событие по записи (переход, комментарий, пауза, помеха, смена
 * ответственного, правка плана, загруженный или собранный документ, завершение
 * и отмена — `touchInteraction` и прямые `update` в `stages/commands.ts`). Это
 * лучше счётчика: обесценивание получается ровно у той записи, по которой
 * работали, а не у всех сразу, и ни одна команда не может «забыть» позвать
 * инвалидацию — она не зовётся вовсе. Момент последнего события читается
 * бесплатно: его возвращает `assertInteractionVisible`, без которого карточку
 * всё равно не отдать.
 *
 * Чего кэш не покрывает: подписи, которые приезжают из других таблиц, — имя
 * ответственного, названия организаций, программ и продуктов в истории правок.
 * Переименование вуза доходит до уже собранной истории по сроку жизни записи, а
 * не мгновенно. Это осознанный размен: иначе в поколение пришлось бы собирать
 * состояние четырёх справочников на каждое открытие карточки.
 *
 * Чего в кэше нет вовсе: контактов людей. Сериализатор `toPersonView`
 * маскирует их по правам **и** оставляет след просмотра персональных данных —
 * ответ, отданный из Redis, этот след потерял бы, а закон требует знать, кто
 * видел контакты. Поэтому стороны карточки читаются из базы каждый раз.
 *
 * Поверх поколения записи в ключе стоит поколение области — счётчик, который
 * обесценивает собранное разом. Он нужен ровно одному случаю: уничтожению
 * персональных данных. Обезличивание переписывает названия и заголовки, в
 * которых стояло ФИО (`people/retention.ts`), но моментом последнего события по
 * взаимодействию **не** двигает — работы по записи не было, и подделывать
 * активность ради сброса кэша нельзя. Без счётчика карточка целую минуту
 * показывала бы то, что объявлено уничтоженным.
 */
import { bumpEpoch, cached, readEpoch, type CacheRegion } from './region';

const INTERACTION_CARD: CacheRegion = { name: 'interaction-card', ttlSeconds: 60 };

/**
 * Собранные карточки больше не показывать.
 *
 * Зовётся после уничтожения персональных данных: оно меняет то, что уже лежит
 * в кэше, не трогая поколение ни одной записи.
 */
export async function invalidateInteractionCards(): Promise<void> {
	await bumpEpoch(INTERACTION_CARD);
}

/**
 * Насколько «свежую» запись в кэш не кладут.
 *
 * `last_activity_at` приходит из PostgreSQL с точностью до микросекунды, а в
 * `Date` остаются миллисекунды. Две записи по одному взаимодействию внутри
 * одной миллисекунды дали бы одно поколение, и чтение между ними попало бы в
 * кэш. Окно в две секунды закрывает этот зазор там, где он вообще может
 * возникнуть, — сразу после события, — и ничего не стоит: карточку, по которой
 * только что работали, кэшировать и незачем.
 */
const SETTLED_AFTER_MS = 2_000;

/**
 * Часть карточки: готовая или собранная заново.
 *
 * `part` называет часть («comments», «changes»), `interaction` — то, что
 * вернула проверка видимости: идентификатор записи и момент последнего события
 * по ней.
 */
export async function cachedInteractionPart<TValue>(
	part: string,
	interaction: { id: string; lastActivityAt: Date },
	build: () => Promise<TValue>,
	revive: (stored: unknown) => TValue
): Promise<TValue> {
	if (Date.now() - interaction.lastActivityAt.getTime() < SETTLED_AFTER_MS) {
		return build();
	}

	const epoch = await readEpoch(INTERACTION_CARD);

	return cached(
		INTERACTION_CARD,
		`${epoch}:${interaction.id}:${interaction.lastActivityAt.toISOString()}:${part}`,
		build,
		revive
	);
}
